    q(90, '②(3)Y', '反射光', '鏡で反射して出ていく光を何というか。', T('反射光', 'はんしゃこう'), 'ワークp90②(3)Y：反射光。', near=['入射光'])
    q(90, '②(4)a', '入射角', '鏡の面に垂直な直線と入射光の間の角度を何というか。', T('入射角', 'にゅうしゃかく'), 'ワークp90②(4)a：入射角。', near=['反射角', '屈折角'])
    q(90, '②(4)b', '反射角', '鏡の面に垂直な直線と反射光の間の角度を何というか。', T('反射角', 'はんしゃかく'), 'ワークp90②(4)b：反射角。', near=['入射角'])
    q(90, '②(5)', '反射の法則', '入射角と反射角がそれぞれ等しくなることを何というか。', T('反射の法則', 'はんしゃのほうそく'), 'ワークp90②(5)：反射の法則。', near=['屈折'])
    q(98, '○×①', '反射の法則', '光が反射するとき、入射角と反射角の関係は「＝・＜・＞」のどれか。', T('＝', '=', '等しい', '同じ'), 'ワークp98○×①：○（入射角＝反射角）。', near=['＜', '>'])
