    q(91, '①(3)', '屈折', '水中から空気中へ入射角30°で光を当てた。屈折角は30°より大きいか、小さいか。', T('大きい', 'おおきい', '大きくなる'), 'ワークp91①(3)：水→空気では屈折角は入射角より大きい。', near=['小さい'])
